mapper.select:
SELECT fbs.id, fbs.park_org_id, fbs.scheme_name, fbs.charge_item_id, fbs.billing_cycle, fbs.reserved_digits, fbs.carry_mode, fbs.formula_type, fbs.amount_with_tax, fbs.amount_without_tax, fbs.calculation_standard, fbs.unit_price_without_tax, fbs.unit_price_with_tax, fbs.charge_type, fbs.charging_cycle, fbs.cumulative_cycle, fbs.day_of_month, fbs.days_for_delay, fbs.late_rate, fbs.exempt_days, fbs.status, fbs.month_by, fbs.late_type, fbs.fee_type, fbs.late_charge, fbs.late_day_amount, fbs.update_time FROM fee_billing_scheme fbs INNER JOIN fee_charge_item fci ON fbs.charge_item_id = fci.id
fbs.deleted = 0
AND fbs.status = #{status}
AND fbs.scheme_name = #{schemeName}
AND fbs.park_org_id = #{parkOrgId}
AND fbs.park_org_id IN
#{parkOrgId}
AND fci.fee_type = #{feeType}
and fci.fee_type in
#{feeType}
order by fbs.update_time desc
